import pages, runpy
from pages import reading as R, story as S, verse as V
from fig import *
from fig2 import *
from fig3 import *
E=pages.EXTRA
B='/festivals/navaratri/'
L=lambda u,t: f'<a href="{u}">{t}</a>'
DM='Text checked against devimahatmyam.aurobharati.in, as on our '
def D(**k): return devi(**k)
def gourd(): return '<ellipse cy="-22" rx="22" ry="24" fill="#cfe0c8"/><path d="M0 -46 q2 -8 8 -10" stroke="#2f7a3a" stroke-width="3" fill="none"/><path d="M-10 -40 q-4 18 0 36 M10 -40 q4 18 0 36" stroke="#9ab89a" fill="none"/>'
def egg(): return '<ellipse rx="22" ry="28" fill="#ffd60a"/><ellipse rx="14" ry="18" fill="#fff8d0" stroke="none"/>'
def bell(): return '<path d="M-14 0 q0 -30 14 -34 q14 4 14 34z" fill="#e0a800"/><circle cy="4" r="4" fill="#e0a800"/><path d="M0 -34 v-6" stroke-width="3"/>'
def reeds(): return ''.join(f'<path d="M{x} 0 q{(-1)**x*4} -30 0 -60" stroke="#7a9a3a" stroke-width="3" fill="none"/>' for x in range(-30,32,6))
def stars6(): return ''.join(f'<circle cx="{-40+k*16}" cy="{-8*(k%2)}" r="4" fill="#ffd60a"/>' for k in range(6))
def buffalo_(): return beast('buffalo')
def lionx(): return beast('lion')
def tree_b(): return tree('#2f6a3a')
def flamecol(): return '<rect x="-14" y="-120" width="28" height="120" fill="#ff8c1a"/><path d="M-14 -120 q14 -20 28 0" fill="#ffd60a"/>'
def sw(): return '<rect x="-30" y="-70" width="60" height="70" fill="#e3eaf3"/><path d="M-30 -70 l30 -20 l30 20" fill="#c0392b"/>'
def gaurd(): return '<rect x="-18" y="-18" width="36" height="18" fill="#c98a5a"/>'
# Night 1
E[B+'shailaputri/']=[
 S('daksha','DAKṢA’S SACRIFICE','How Satī left her body',strip('Three panels: Dakṣa at his sacrifice insulting Śiva; Satī entering the yogic fire; Vīrabhadra destroying the sacrifice',[panel([(god('#7a3fa0'),1),(agni(),.9)],'#fde4e4',150),panel([(D(sari='#c0392b',items=('lotus',)),.9),(flames(),.9)],'#2a2a3a',150),panel([(demon('#2a2a3a'),1),(agni(),.7)],'#e9e3f5',150)],['the insult','Satī’s fire','Vīrabhadra']),'Bhāgavata Purāṇa 4.2–5 and the Śiva Purāṇa; Śailaputrī’s story begins with Satī’s end.',['<b>Dakṣa</b>, son of Brahmā, held a grudge against his son-in-law Śiva, the ash-smeared ascetic who had not stood up to greet him. He held a great sacrifice and invited every god but Śiva.','<b>Satī</b>, Dakṣa’s daughter and Śiva’s wife, went anyway, against Śiva’s warning, hoping to see her family. Her father ignored her and mocked her husband before the assembly.','Unable to bear the insult to Śiva, Satī sat on the ground, entered yogic concentration, and gave up her body in an inner fire.','When Śiva heard, he tore a lock of his hair and from it rose <b>Vīrabhadra</b>, who wrecked the sacrifice and beheaded Dakṣa; later Śiva relented and Dakṣa was given a goat’s head.','In the Śākta tellings Śiva wandered the world carrying Satī’s body, and where its parts fell arose the '+L('/temples-of-india/18-shakti-peethas/','Śakti Pīṭhas')+'. Satī was reborn as the daughter of the mountain: <b>Śailaputrī</b>.'],[('z','So Night 1 begins with a loss?'),('b','With a death and a rebirth, Zappy. The Goddess comes back as the mountain’s daughter, stronger and steadier.')],'A death that <b>becomes a rebirth</b>.'),
 R('himavan','HIMAVĀN AND MENĀ','The mountain family',svg(560,180,'A snow mountain with a king and queen before it and a little girl between them',ground(560,180,150,'#e3eaf3')+g(280,150,1.6,mountain('#c9d6e6',True))+g(200,170,1,god('#7a3fa0'))+g(360,170,1,person('#2a9d6f'))+g(280,170,.8,child())),['<b>The king of mountains.</b> Kālidāsa opens his Kumārasambhava with the Himālaya as “the king of mountains, whose soul is divine”, standing in the north like a measuring rod of the earth. In the Purāṇas the mountain is also a person, <b>Himavān</b>, with a queen, <b>Menā</b>.','<b>The household.</b> Their children include <b>Pārvatī</b> (“of the mountain”) and, in many tellings, the river <b>Gaṅgā</b>; their son Maināka is the mountain that hid in the sea. So Śailaputrī’s brother is a mountain and her sister a river.','<b>A daughter given to Śiva.</b> Himavān and Menā gave Pārvatī to Śiva at the wedding told on '+L(B+'chandraghanta/','Night 3')+'; Menā’s horror at Śiva’s wild wedding party is one of the Purāṇas’ comic scenes.','<b>Why a mountain.</b> Many teachers read Śailaputrī as steadiness: the first night asks the devotee to be as firm as the mountain before the climb of the nine nights. (Interpretation.)'],[('z','Pārvatī’s sister is the Gaṅgā?'),('b','In many tellings, Zappy. A family of mountains and rivers: the whole Himālaya at home.')],'A family of <b>mountains and rivers</b>.')]
# Night 2
E[B+'brahmacharini/']=[
 S('saptarshi','THE SEVEN SAGES’ TEST','A second test of her resolve',strip('Three panels: seven sages arriving at Pārvatī’s hermitage; the sages praising Viṣṇu as a better husband; Pārvatī refusing firmly',[panel([(sage('#ff8c1a'),.7),(sage('#e0a800'),.7),(sage('#c98a3a'),.7)],'#fff3cf',150),panel([(sage('#ff8c1a'),.8),(vishnu(),.7)],'#e3eaf3',150),panel([(D(sari='#fff',items=('rosary','kamandalu')),1)],'#e9e3f5',150)],['the sages come','a “better” match','she refuses']),'Śiva Purāṇa, Rudra Saṃhitā, Pārvatī Khaṇḍa.',['While Pārvatī did her penance, Śiva sent the <b>seven sages</b>, the Saptarṣis, to see how firm her mind was.','They spoke against Śiva: a homeless wanderer with snakes and ash, who had already destroyed Kāma and cared for no one. Why not marry Viṣṇu, lord of Vaikuṇṭha, rich and gracious?','Pārvatī answered calmly: she knew who Śiva was, she had chosen him, and she would marry him or no one, even if it took a thousand births.','The sages, delighted, blessed her and went back to Śiva with the report: her resolve could not be shaken.','Soon after, Śiva came himself in disguise to test her once more (told earlier in this article). '+'Brahmacāriṇī, the night’s goddess, is this young woman of unbreakable vow.'],[('z','They tested her twice?'),('b','A real vow gets tested more than once, Zappy. That’s how you know it’s real.')],'A vow <b>tested and unshaken</b>.'),
 R('tapas','WHAT TAPAS MEANS','The heat of discipline',svg(560,180,'A young woman meditating between four fires under the summer sun',ground(560,180,150,'#fde9c8')+g(280,40,1,sun(20))+g(280,165,1.1,D(sari='#fff',items=('rosary','kamandalu'),seat=True))+''.join(g(x,170,.8,flames()) for x in (150,210,350,410))),['<b>Heat.</b> <i>Tapas</i> literally means heat: the inner fire produced by discipline. In the Vedas the creator himself makes the world by tapas; in the Purāṇas gods and demons alike win boons by it.','<b>Pārvatī’s tapas.</b> Kālidāsa (Kumārasambhava, canto 5) describes it season by season: in summer she sat between four fires with the sun as the fifth; in the rains she slept on bare rock; in winter she stood in icy water; at last she gave up even fallen leaves, earning the name <b>Aparṇā</b>.','<b>The rosary and the water-pot.</b> Brahmacāriṇī holds a japa-mālā and a kamaṇḍalu: the student’s and the ascetic’s simple tools. Her white sari is the plainest dress of any of the nine.','<b>For students.</b> <i>Brahmacarya</i> is also the student stage of life. Many families pray to Brahmacāriṇī for focus before examinations. (Popular practice.)'],[('z','Do I need to sit between fires?'),('b','No, Zappy. Tapas today is getting up early to study when you’d rather sleep. Same heat, smaller fire.')],'Discipline is <b>a kind of fire</b>.')]
# Night 3
E[B+'chandraghanta/']=[
 S('weapons','THE GODS ARM THE GODDESS','Where the bell came from',strip('Three panels: light rising from the gods into one radiant goddess; the gods giving her weapons; Indra giving the bell from his elephant Airāvata',[panel([(god(),.6),(god('#e0a800'),.6),(D(),.8)],'#fff3cf',150),panel([(D(),.8),(trident(),.8),(discus(),.6)],'#fde4e4',150),panel([(elephant(False),.5),(bell(),1.2)],'#e3eaf3',150)],['one light','the gifts','the bell']),'Devī Māhātmya, chapter 2.',['When Mahiṣāsura drove the gods from heaven, their anger blazed out of their faces as light, and the light gathered into one radiant Goddess.','Each god then gave her a copy of his own weapon: Śiva a trident, Viṣṇu a discus, Varuṇa a conch and a noose, Agni a spear, Vāyu a bow and quivers.','<b>Indra</b> gave her his thunderbolt, and took a <b>bell</b> from his elephant <b>Airāvata</b> and gave it to her too (next page).','Himavān gave her the lion; Kubera a cup; Viśvakarman an axe and armour; the ocean garlands of unfading lotuses.','So armed, she laughed aloud, and the worlds shook. Candraghaṇṭā, with the bell-shaped moon and the bell whose sound terrifies demons, is that Goddess ready for battle.'],[('z','The bell came from an elephant?'),('b','Airāvata’s war-bell, Zappy. When she rings it, the demons’ courage breaks.')],'Every god’s gift <b>in one pair of hands</b>.'),
 V('v-bell','Devī Māhātmya 2.23','The bell from Airāvata',['dadau tasyai sahasrākṣo ghaṇṭām airāvatād gajāt','kāladaṇḍād yamo daṇḍaṃ pāśaṃ cāmbupatir dadau'],svg(220,160,'A bell and an elephant beside the Goddess',ground(220,160,140,'#e3eaf3')+g(70,140,.6,elephant(False))+g(150,140,.8,D())+g(110,60,1.3,bell()),cls=''),'The thousand-eyed (Indra) gave her a bell from his elephant Airāvata; Yama gave her a staff from his staff of death, and the lord of the waters (Varuṇa) a noose.',[('sahasrākṣaḥ','the thousand-eyed, Indra'),('ghaṇṭām','a bell'),('airāvatāt gajāt','from the elephant Airāvata'),('kāla-daṇḍāt','from the staff of death'),('pāśam','a noose'),('ambupatiḥ','lord of the waters')],'<b>Why the bell matters.</b> Every Hindu pūjā rings a bell at the start, to invite the gods and drive away the demons, as the pūjā manuals say. Candraghaṇṭā takes her very name from it: the moon shaped like a bell on her forehead, and the war-bell from Indra in her hand.',None,'The bell of <b>war and worship</b>.',DM+L('/devi/devi-mahatmya/part-7/','Devī Māhātmya part 7')+' page.')]
# Night 4
E[B+'kushmanda/']=[
 R('egg','THE GOLDEN EGG','Creation in the older texts',svg(560,180,'A golden egg floating on dark waters, light spreading from it',ground(560,180,180,'#20243a')+'<rect y="120" width="560" height="60" fill="#2a3a5a"/>'+g(280,100,2,egg())+''.join(f'<path d="M280 100 l{110*__import__("math").cos(k*0.52):.0f} {70*__import__("math").sin(k*0.52):.0f}" stroke="#ffd60a" stroke-width="2"/>' for k in range(12))),['<b>Hiraṇyagarbha.</b> The Ṛgveda (10.121) praises <b>Hiraṇyagarbha</b>, the golden embryo, that arose in the beginning and became the one lord of all that is. Later texts describe the universe as an egg, the <b>Brahmāṇḍa</b>, “Brahmā’s egg”, floating on the primal waters.','<b>Kūṣmāṇḍā’s name.</b> Her name is often explained as <i>ku</i> (a little) + <i>ūṣma</i> (warmth) + <i>aṇḍa</i> (egg): she who made the cosmic egg with a little warmth, her smile. The explanation is popular; the word kūṣmāṇḍa also simply means a gourd (next page).','<b>Light in the dark.</b> The Navarātri telling says that before creation there was only darkness, and her smile was the first light; she lives in the heart of the sun. The Devī Māhātmya likewise calls the Goddess the creator, sustainer and destroyer of all (1.75–76).','<b>Many tellings, one idea.</b> Whether egg, embryo or smile, the Hindu creation stories agree that the world begins as warmth and light in the dark. (Our reading.)'],[('z','A smile made the universe?'),('b','A warm smile in the dark, Zappy. Physicists talk of a hot beginning too.')],'The world from <b>a little warmth</b>.'),
 R('gourd','THE ASH GOURD','Kūṣmāṇḍa in Karnataka homes',svg(560,180,'An ash gourd hung over a doorway with a painted face, and another being broken before a vehicle',ground(560,180,150,'#fde9c8')+'<rect x="90" y="20" width="120" height="130" fill="#c9a06a"/><rect x="110" y="50" width="80" height="100" fill="#5a3a2a"/>'+g(150,40,.8,gourd())+g(380,150,1.2,gourd())+g(470,150,.8,'<rect x="-40" y="-40" width="80" height="34" rx="8" fill="#2a5aa8"/><circle cx="-24" cy="-4" r="8" fill="#333"/><circle cx="24" cy="-4" r="8" fill="#333"/>')),['<b>The word.</b> <i>Kūṣmāṇḍa</i> in Sanskrit is the ash gourd (white pumpkin), <b>būdu kumbaḷakāyi</b> in Kannada, and tradition says Kūṣmāṇḍā loves it as an offering.','<b>The offering that replaced blood.</b> In many temples and homes the ash gourd is offered and broken as a <b>kūṣmāṇḍa bali</b>, a sacrifice in place of an animal; it is marked with turmeric and kuṅkuma and cut or smashed.','<b>Āyudha Pūjā.</b> On '+L(B+'mahanavami-vijayadashami/','Mahānavamī')+' Karnataka breaks ash gourds before vehicles, shops and machines to ward off the evil eye, and many new houses hang a painted gourd over the door all year for the same reason.','<b>In the kitchen.</b> The gourd’s halwa (<i>kāśi halva</i>) and mōr kuḻambu-style curries are everyday South Indian food; some families avoid cutting it on certain days out of respect. (Customs vary.)'],[('z','So the gourd on our neighbour’s door is for her?'),('b','It’s for protection, Zappy, and the tradition ties it to Kūṣmāṇḍā. Next time you see one, you’ll know the name.')],'A gourd <b>for the Goddess</b>.')]
# Night 5
E[B+'skandamata/']=[
 S('krittikas','THE SIX MOTHERS','How Skanda got six faces',strip('Three panels: Śiva’s seed carried by Agni into the Gaṅgā; six babies in a reed pond nursed by six star-women; Pārvatī gathering them into one six-faced child',[panel([(agni(),.9),(river(144,120),1)],'#fde4e4',None),panel([(reeds(),1),(stars6(),1),(baby(),.6)],'#e3f5e9',150),panel([(D(sari='#2a9d6f',items=('lotus',)),.9),(baby(),.7)],'#fff3cf',150)],['fire and river','the reed pond','one child, six faces']),'Mahābhārata (Vana Parvan) and the Śiva and Skanda Purāṇas; tellings differ in detail.',['Only a son of Śiva could kill the demon Tāraka. Śiva’s fiery seed was too hot for anyone to hold: <b>Agni</b>, the fire god, carried it and gave it to the <b>Gaṅgā</b>.','The river could not bear it either and left it in a thicket of reeds (<i>śara-vaṇa</i>) by her bank. There a child was born: <b>Śaravaṇabhava</b>.','The six <b>Kṛttikās</b>, the Pleiades, came to bathe, found the child, and each wanted to nurse him; he grew six faces to drink from all six. Hence <b>Kārttikeya</b> and <b>Ṣaṇmukha</b>.','Pārvatī came, took him in her arms, and (in the southern telling) gathered six infants into one child with six faces and twelve arms.','So Skanda has many mothers and one mother: Skandamātā is Pārvatī holding him on her lap. His war is told in our '+L('/subramanya/shashthi/','Ṣaṣṭhī')+' article.'],[('z','Six mothers?'),('b','Six star-mothers and one Goddess, Zappy. Many tellings, one well-loved child.')],'Six mothers, <b>one lap</b>.'),
 R('mother','THE MOTHER AS POWER','Why the warrior’s mother is worshipped',svg(560,180,'A seated goddess on a lion with a child on her lap and lotuses in her hands',ground(560,180,160,'#e3f5e9')+g(280,165,1,lionx())+g(280,125,1,D(sari='#2a9d6f',items=('lotus','lotus'),seat=True))+g(300,110,.5,baby())),['<b>The image.</b> Skandamātā sits on a lion, holding lotuses, with the child Skanda on her lap. She is a mother first; the lion says her motherhood has a warrior’s strength.','<b>Mother of the general.</b> Skanda leads the gods’ army; the Goddess who bore and raised him stands behind every victory. Many read the fifth night as the honour due to every mother. (Interpretation.)','<b>In Karnataka.</b> Skanda is Subrahmaṇya, worshipped at '+L('/subramanya/kukke/','Kukke')+' and '+L('/subramanya/ghati/','Ghāṭi')+'; on this night families who keep Subrahmaṇya vows often remember him with his mother.','<b>Children.</b> Couples praying for children, and parents praying for them, often keep this night with special care. (Popular practice.)'],[('z','The general’s mother gets her own night?'),('b','Of course, Zappy. Where do you think he learned courage?')],'Behind the hero, <b>the mother</b>.')]
# Night 6
E[B+'katyayani/']=[
 S('vamana','BORN IN KĀTYĀYANA’S HERMITAGE','The light of the gods’ anger',strip('Three panels: the gods’ anger streaming out as light; the light gathering at the sage Kātyāyana’s hermitage into a goddess; the goddess riding out on a lion',[panel([(god(),.7),(god('#e0a800'),.7),(flamecol(),.4)],'#fde4e4',150),panel([(sage('#ff8c1a'),.8),(D(),.8)],'#fff3cf',150),panel([(lionx(),.6),(D(items=('sword','lotus')),.6)],'#e9e3f5',150)],['the gods’ anger','at Kātyāyana’s hermitage','to battle']),'Vāmana Purāṇa (chs. 18–21 in common numbering); the Navarātri tradition follows it.',['Mahiṣāsura had driven the gods from heaven. They went to Viṣṇu and Śiva, and their fury blazed out of them as fire.','The fires of all the gods flowed together, says the Vāmana Purāṇa, at the hermitage of the sage <b>Kātyāyana</b>, and there became one blazing Goddess.','The sage worshipped her first, and so she was called <b>Kātyāyanī</b>, “of Kātyāyana”. (Another telling: she was born as his daughter after his long penance.)','The gods armed her, Himavān gave her a lion, and she went out to the Vindhya mountains to meet Mahiṣa.','She destroyed his army and slew the buffalo-demon himself: Kātyāyanī is Mahiṣāsuramardinī. The full battle is told in '+L(B+'the-story/','Part 2')+'.'],[('z','Born from anger?'),('b','From righteous anger, Zappy, gathered and given to someone who could use it well.')],'Anger turned <b>into a Goddess</b>.'),
 R('mysuru','MAHIṢĀSURA AND MYSURU','The city named for the demon',svg(560,180,'A hill with a temple on top and a large statue of a demon holding a snake and sword below it',ground(560,180,160,'#fde9c8')+g(380,170,1.4,mountain('#9a8a6a',False))+g(380,90,.6,palace())+g(170,170,1.4,demon('#2a3a5a'))),['<b>The name.</b> Mysuru’s name is traditionally derived from <b>Mahiṣūru</b>, “the town of Mahiṣa”: local tradition holds that the buffalo-demon ruled here and was slain on the hill above the city by the Goddess as <b>Cāmuṇḍeśvarī</b>.','<b>Cāmuṇḍi Hill.</b> On the hill stands her temple, and on the way up a huge painted statue of Mahiṣāsura with a sword and a cobra, one of Mysuru’s landmarks. See our '+L('/temples-of-india/around-mysuru/chamundeshwari/','Cāmuṇḍeśvarī')+' guide.','<b>The Dasarā.</b> The '+L(B+'mysuru-dasara/','Mysuru Dasarā')+' celebrates her victory: it is opened on the hill and ends with her golden image carried through the city on Vijayadaśamī.','<b>Kātyāyanī and Cāmuṇḍā.</b> In the Navarātri list the slayer of Mahiṣa is Kātyāyanī; in Mysuru she is Cāmuṇḍeśvarī. The Devī Māhātmya gives the name Cāmuṇḍā to the Goddess who killed Caṇḍa and Muṇḍa (chapter 7); local tradition gives her the buffalo-demon too. Traditions combine freely.'],[('z','Mysuru is named after the demon?'),('b','After the place he ruled, by tradition, Zappy. And the Goddess on the hill has watched over it since.')],'The demon’s town, <b>the Goddess’s city</b>.')]
# Night 7
E[B+'kalaratri/']=[
 V('v-kalaratri','Devī Māhātmya 1.78','The night of time in the first hymn',['prakṛtis tvaṃ ca sarvasya guṇatrayavibhāvinī','kālarātrir mahārātrir moharātriś ca dāruṇā'],svg(220,160,'A dark night sky with three crescent moons for the three nights',ground(220,160,160,'#20243a')+''.join(f'<path d="M{x} 50 a18 18 0 1 0 14 30 a14 14 0 1 1 -14 -30z" fill="#fff8d0" stroke="none"/>' for x in (50,110,170))+g(110,150,.7,D(skin='#2a2a3a',sari='#2a2a3a',items=('sword','abhaya'))),cls=''),'You are the primal nature of all, bringing forth the three qualities; you are the night of time, the great night, and the terrible night of delusion.',[('prakṛtiḥ','primal nature'),('guṇa-traya','the three qualities'),('kāla-rātriḥ','the night of time'),('mahā-rātriḥ','the great night'),('moha-rātriḥ','the night of delusion'),('dāruṇā','terrible')],'<b>Her name in the oldest hymn.</b> In Brahmā’s hymn to the Goddess at the start of the Devī Māhātmya, Kālarātri is already one of her names: the night in which time itself dissolves the world. Many explain the three nights as the dissolution of the world (kālarātri), the great night of Śiva (mahārātri, often linked with Śivarātri) and the night of delusion (moharātri, often linked with Janmāṣṭamī). (Common interpretation.)',None,'Even the dark is <b>a form of the Goddess</b>.',DM+L('/devi/devi-mahatmya/part-6/','Devī Māhātmya part 6')+' page.'),
 R('shubhankari','WHY SHE IS ŚUBHAṄKARĪ','The fearsome one who does good',svg(560,180,'A dark goddess on a donkey with one hand raised in blessing and the other holding a sword',ground(560,180,160,'#3a2a3a')+g(280,170,1,beast('donkey','#6a6a6a'))+g(280,130,1,D(skin='#2a2a3a',sari='#2a2a3a',items=('sword','abhaya')))),['<b>Two names.</b> Kālarātri is the most frightening of the nine: black, wild-haired, breathing fire, riding a donkey. Yet she is also called <b>Śubhaṅkarī</b>, “she who does good”.','<b>Her hands.</b> One hand holds a cleaver or sword, another a hook or thorn-club; the other two show <b>abhaya</b> (do not fear) and <b>varada</b> (I give). The terror is aimed at what harms the devotee, the blessing at the devotee.','<b>The donkey.</b> Her mount is the humblest animal: no lion or bull, just the patient beast of burden. Many read it as a sign that she is close to the lowly. (Interpretation.)','<b>The seventh night.</b> In many South Indian homes the seventh day is also when Sarasvatī is invited on the Mūla star (read '+L(B+'sarasvati-puja-durgashtami/','Part 14')+'): the darkest goddess and the brightest arrive together.'],[('z','How can scary be kind?'),('b','A fierce mother is kind to her child and terrible to whatever threatens it, Zappy.')],'Fierce to fear, <b>kind to you</b>.')]
# Night 8
E[B+'mahagauri/']=[
 V('v-kaushiki','Devī Māhātmya 5.87–88','From Pārvatī’s body, Kauśikī',['śarīrakośād yat tasyāḥ pārvatyā niḥsṛtāmbikā','kauśikīti samasteṣu tato lokeṣu gīyate','tasyāṃ vinirgatāyāṃ tu kṛṣṇābhūt sāpi pārvatī','kāliketi samākhyātā himācalakṛtāśrayā'],svg(220,160,'A radiant white goddess stepping out of a dark goddess',ground(220,160,150,'#e3eaf3')+g(80,150,.8,D(skin='#2a2a3a',sari='#2a2a3a'))+g(150,150,.8,D(skin='#fbeee0',sari='#fff')),cls=''),'Because Ambikā came forth from the sheath (kośa) of Pārvatī’s body, she is sung in all the worlds as Kauśikī. When she had come forth, Pārvatī herself became dark, and was known as Kālikā, dwelling on the Himālaya.',[('śarīra-kośāt','from the sheath of her body'),('niḥsṛtā','came forth'),('kauśikī','she of the sheath'),('kṛṣṇā abhūt','became dark'),('kālikā','Kālikā, the dark one'),('himācala-kṛta-āśrayā','dwelling on the Himālaya')],'<b>White and dark.</b> In the Devī Māhātmya a radiant goddess, Kauśikī, steps out of Pārvatī, and Pārvatī becomes dark Kālikā. The Śiva Purāṇa tells it the other way round: Pārvatī, teased by Śiva for her dark skin, does penance and sheds it to become <b>Gaurī</b>, the fair one, while the dark sheath becomes Kauśikī. Either way, the Goddess holds both, and Mahāgaurī is her radiant form.',None,'One Goddess, <b>dark and radiant</b>.',DM+L('/devi/devi-mahatmya/part-10/','Devī Māhātmya part 10')+' page.'),
 R('white','WHY WHITE?','Mahāgaurī and the eighth day',svg(560,180,'A white goddess on a white bull with jasmine flowers and little girls before her',ground(560,180,160,'#e3eaf3')+g(220,170,1,beast('bull','#f4f1ea'))+g(220,130,1,D(skin='#fbeee0',sari='#fff',items=('trident','damaru')))+g(380,170,.8,child())+g(430,170,.8,child())),['<b>All white.</b> Mahāgaurī is white as a conch, the moon and jasmine; she rides a white bull and wears white. White is the colour of purity and of peace after the battle.','<b>Durgāṣṭamī.</b> The eighth night is <b>Durgāṣṭamī</b>, one of the great days of Navarātri, with the junction-hour Sandhi Pūjā and, in many homes, <b>Kanyā Pūjā</b>, the worship of little girls as the Goddess (read '+L(B+'sarasvati-puja-durgashtami/','Part 14')+').','<b>Gaurī the girl.</b> In older usage <i>gaurī</i> was also the name for a girl of about eight years, which ties the eighth night to the girls worshipped on it. (Tradition; our reading of the link.)','<b>Washing away.</b> The night’s story, told earlier in this article, is of her dark skin washed in the Gaṅgā: many read it as the mind cleaned by the long effort of the earlier nights. (Interpretation.)'],[('z','So white means the work is done?'),('b','Nearly done, Zappy. The battle is over; what is left is peace and one more night.')],'After the battle, <b>white peace</b>.')]
# Night 9
E[B+'siddhidatri/']=[
 R('siddhis','THE EIGHT SIDDHIS','What “perfection” means',svg(560,180,'Eight symbols in a circle around a seated goddess on a lotus',ground(560,180,160,'#fff3cf')+g(280,165,1,D(sari='#c0392b',items=('discus','conch','mace','lotus'),seat=True))+''.join(g(280+190*__import__("math").cos(3.14+k*0.45),165+120*__import__("math").sin(3.14+k*0.45),.7,lamp()) for k in range(8))),['<b>The list.</b> The eight great siddhis, yogic powers, are commonly listed as <b>aṇimā</b> (becoming tiny), <b>mahimā</b> (becoming vast), <b>garimā</b> (heavy), <b>laghimā</b> (light), <b>prāpti</b> (reaching anywhere), <b>prākāmya</b> (fulfilling any wish), <b>īśitva</b> (mastery) and <b>vaśitva</b> (control). Lists vary slightly.','<b>The giver.</b> Siddhidātrī is “the giver of siddhis”: the Navarātri tradition says even Śiva received them from her. Hanumān too is praised in the Cālīsā as “giver of the eight siddhis and nine treasures, by Jānakī’s boon” ('+L('/hanuman/chalisa/','Cālīsā')+' 31).','<b>A warning.</b> The Yoga Sūtra (3.37) treats such powers as obstacles to the highest goal, attainments of the outward-turned mind. The true siddhi, many teachers say, is liberation itself. (Interpretation.)','<b>Perfection as completion.</b> On the ninth night, the word means simply this: what was begun on the first night is completed.'],[('z','Could I become tiny?'),('b','Ask Hanumān, Zappy! For the rest of us the real siddhi is finishing what we start.')],'The true perfection: <b>completion</b>.'),
 V('v-promise','Devī Māhātmya 12.12–13','The Goddess’s promise for the autumn worship',['śaratkāle mahāpūjā kriyate yā ca vārṣikī','tasyāṃ mamaitan māhātmyaṃ śrutvā bhaktisamanvitaḥ','sarvābādhāvinirmukto dhanadhānyasamanvitaḥ','manuṣyo matprasādena bhaviṣyati na saṃśayaḥ'],svg(220,160,'A family reading a book before the Goddess in autumn',ground(220,160,150,'#fde9c8')+g(150,150,.8,D())+g(70,150,.8,person('#2a5aa8',seat=True))+g(80,110,.8,book()),cls=''),'At the great annual worship in autumn, whoever hears this glorification of mine with devotion will be freed from all troubles and blessed with wealth and grain, by my grace; there is no doubt.',[('śarat-kāle','in the autumn season'),('mahā-pūjā','the great worship'),('vārṣikī','yearly'),('bhakti-samanvitaḥ','full of devotion'),('sarva-ābādhā-vinirmuktaḥ','freed from all troubles'),('mat-prasādena','by my grace')],'<b>Why Navarātri is in autumn.</b> At the end of the Devī Māhātmya the Goddess herself names the <b>autumn great worship</b> (śarat-kāla mahāpūjā) as the time to hear her story. That is the scriptural root of Śāradīya Navarātri, and why many families finish reading the whole Devī Māhātmya by the ninth night.',None,'Her own promise <b>for the autumn worship</b>.',DM+L('/devi/devi-mahatmya/part-17/','Devī Māhātmya part 17')+' page.')]
# Sarasvatī / Durgāṣṭamī
E[B+'sarasvati-puja-durgashtami/']=[
 R('karnataka','SARASVATĪ IN KARNATAKA','Śṛṅgeri, Kollūr and the first letters',svg(560,180,'A riverside temple, a hill temple and a child writing letters in rice with an elder',ground(560,180,160,'#e3eaf3')+'<path d="M0 150 q140 -10 280 0" stroke="#8fb8de" stroke-width="10" fill="none"/>'+g(130,150,.7,palace())+g(300,170,.9,mountain('#6a8a5a',False))+g(300,110,.4,palace())+g(450,170,.9,sage('#ff8c1a'))+g(500,170,.7,child())),['<b>Śṛṅgeri.</b> On the Tuṅgā river, the Śāradā Pīṭha founded by tradition by Ādi Śaṅkara keeps a grand Navarātri: the Goddess <b>Śāradā</b> is decorated in a different form each day (as Brahmāṇī, Vaiṣṇavī, Gajalakṣmī and others), with the Sarasvatī form on the Mūla day.','<b>Kollūr.</b> At Kollūr, below the Kodachādri hills, the Goddess <b>Mūkāmbikā</b> is visited by thousands for <b>vidyārambha</b> on Vijayadaśamī: children write their first letters in rice on a plate, guided by an elder.','<b>At home.</b> Families place books, pens, musical instruments and today laptops before Sarasvatī on Mūla and leave them till Vijayadaśamī; children are told not to study for those days, then begin again blessed.','<b>Music.</b> Navarātri is also a season of concerts and of musicians worshipping their instruments: Sarasvatī holds the vīṇā.'],[('z','Can laptops be worshipped?'),('b','Whatever you learn with, Zappy. Sarasvatī isn’t fussy about the tools, only the learning.')],'Learning, <b>placed before the Goddess</b>.')]
# Mahānavamī
E[B+'mahanavami-vijayadashami/']=[
 V('v-garja','Devī Māhātmya 3.38','“Roar, fool, while I drink”',['garja garja kṣaṇaṃ mūḍha madhu yāvat pibāmy aham','mayā tvayi hate ’traiva garjiṣyanty āśu devatāḥ'],svg(220,160,'The Goddess on her lion facing a roaring buffalo demon',ground(220,160,150,'#fde4e4')+g(70,150,.7,lionx())+g(70,115,.7,D(items=('sword','trident')))+g(160,150,.8,buffalo_()),cls=''),'Roar, roar for a moment, fool, while I drink this honey; when I have slain you here, the gods will soon be roaring.',[('garja','roar'),('kṣaṇam','for a moment'),('mūḍha','fool'),('madhu','honey, sweet drink'),('tvayi hate','when you are slain'),('garjiṣyanti','will roar')],'<b>The last moment of the battle.</b> Mahiṣa changed shape again and again (buffalo, lion, man with sword, elephant) and then came back as a buffalo. The Goddess drank, laughed, spoke this line, leapt on him, pinned his neck with her foot and struck him with her trident; as he came half out of the buffalo’s mouth she cut off his head (3.40–42). Tradition places the victory at the close of the nine nights; Vijayadaśamī is its celebration.',None,'The battle ends; <b>the gods roar</b>.',DM+L('/devi/devi-mahatmya/part-8/','Devī Māhātmya part 8')+' page.')]
